"""Robinhood 구조 표(kb/structs/robinhood/*.csv)를 씀. 열은 kb/structs/kraken 표를 따름."""
import csv, os, sys

ROOT = sys.argv[1]
OUT = os.path.join(ROOT, 'kb', 'structs', 'robinhood')
os.makedirs(OUT, exist_ok=True)


def w(name, head, rows):
    with open(os.path.join(OUT, name), 'w', encoding='utf-8', newline='') as f:
        c = csv.writer(f)
        c.writerow(head)
        c.writerows(rows)
    print(name, len(rows))


